import { JobEvent } from "../domain/events";
import { JobView, statusForExit } from "../domain/job";
import { JobViewStore } from "../store/jobViewStore";

/** Folds job events into the read model the console API serves. */
export class JobProjection {
  constructor(private readonly store: JobViewStore) {}

  apply(e: JobEvent): void {
    switch (e.kind) {
      case "started":
        this.store.put({
          id: e.jobId,
          name: e.name,
          status: "running",
          exitCode: null,
          log: [],
          seq: 0,
          startedAt: e.at,
          endedAt: null,
        });
        return;
      case "timeline": {
        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
        if (e.seq <= view.seq) return; // stale snapshot
        this.store.put({ ...view, status: "running", log: e.lines, seq: e.seq });
        return;
      }
      case "closed": {
        const view = this.store.get(e.jobId) ?? this.blank(e.jobId);
        this.store.put({ ...view, status: statusForExit(e.exitCode), exitCode: e.exitCode, endedAt: e.at });
        return;
      }
    }
  }

  private blank(id: string): JobView {
    return { id, name: id, status: "running", exitCode: null, log: [], seq: 0, startedAt: 0, endedAt: null };
  }
}
import { JobView } from "../domain/job";

export class JobViewStore {
  private readonly views = new Map<string, JobView>();

  get(id: string): JobView | undefined {
    const v = this.views.get(id);
    return v ? { ...v, log: [...v.log] } : undefined;
  }

  put(view: JobView): void {
    this.views.set(view.id, { ...view, log: [...view.log] });
  }

  delete(id: string): boolean {
    return this.views.delete(id);
  }

  /** Newest first. */
  list(): JobView[] {
    return [...this.views.values()]
      .sort((a, b) => b.startedAt - a.startedAt || (a.id < b.id ? -1 : 1))
      .map((v) => ({ ...v, log: [...v.log] }));
  }
}
import { ConsoleConfig } from "../config";
import { isJobEvent } from "../domain/events";
import { JobView } from "../domain/job";
import { JobProjection } from "../projection/jobProjection";
import { Launcher } from "../service/launcher";
import { JobViewStore } from "../store/jobViewStore";

export interface Response {
  status: number;
  body: unknown;
}

export interface JobDetail {
  id: string;
  name: string;
  status: string;
  exitCode: number | null;
  log: string[];
  truncated: boolean;
}

export class JobsHandler {
  constructor(
    private readonly store: JobViewStore,
    private readonly launcher: Launcher,
    private readonly projection: JobProjection,
    private readonly config: ConsoleConfig,
  ) {}

  detail(id: string): Response {
    const v = this.store.get(id);
    if (!v) return { status: 404, body: { error: `no job ${id}` } };
    return { status: 200, body: this.present(v) };
  }

  list(): Response {
    const rows = this.store.list().map((v) => ({ id: v.id, name: v.name, status: v.status, lines: v.log.length }));
    return { status: 200, body: rows };
  }

  launch(body: unknown): Response {
    const b = (body ?? {}) as { name?: string; command?: string };
    try {
      return { status: 201, body: { id: this.launcher.launch(b.name ?? "", b.command ?? "") } };
    } catch (e) {
      return { status: 400, body: { error: (e as Error).message } };
    }
  }

  /** Events forwarded by remote runners (other hosts). They arrive in whatever order the network delivers. */
  ingest(body: unknown): Response {
    const events = Array.isArray(body) ? body : [body];
    let accepted = 0;
    for (const e of events) {
      if (!isJobEvent(e)) continue;
      this.projection.apply(e);
      accepted++;
    }
    return { status: 202, body: { accepted } };
  }

  private present(v: JobView): JobDetail {
    const max = this.config.maxLogLines;
    const truncated = v.log.length > max;
    return {
      id: v.id,
      name: v.name,
      status: v.status,
      exitCode: v.exitCode,
      log: truncated ? v.log.slice(v.log.length - max) : v.log,
      truncated,
    };
  }
