export interface StartedEvent {
  kind: "started";
  jobId: string;
  name: string;
  at: number;
}

/** Full log snapshot so far. `seq` increases per job. */
export interface TimelineEvent {
  kind: "timeline";
  jobId: string;
  seq: number;
  lines: string[];
}

export interface ClosedEvent {
  kind: "closed";
  jobId: string;
  exitCode: number;
  at: number;
}

export type JobEvent = StartedEvent | TimelineEvent | ClosedEvent;

export function isJobEvent(x: unknown): x is JobEvent {
  if (typeof x !== "object" || x === null) return false;
  const e = x as { kind?: unknown; jobId?: unknown };
  if (typeof e.jobId !== "string") return false;
  return e.kind === "started" || e.kind === "timeline" || e.kind === "closed";
}
export type JobStatus = "running" | "succeeded" | "failed";

export interface JobView {
  id: string;
  name: string;
  status: JobStatus;
  exitCode: number | null;
  log: string[];
  seq: number;
  startedAt: number;
  endedAt: number | null;
}

export function statusForExit(code: number): JobStatus {
  return code === 0 ? "succeeded" : "failed";
}

export function isFinished(v: JobView): boolean {
  return v.status !== "running";
}
/** What the console can observe about a running child process. */
export interface ProcessHandle {
  /** Raw output chunks written so far (may contain ANSI escapes and \r). */
  output(): string[];
  /** Exit code once the process has exited, otherwise null. */
  exitCode(): number | null;
}

export interface ScriptStep {
  /** Milliseconds after the process was started. */
  at: number;
  write?: string;
  exit?: number;
}

/** Deterministic stand-in for a child process, driven by the console clock. */
export class ScriptedProcess implements ProcessHandle {
  private readonly startedAt: number;

  constructor(private readonly steps: ScriptStep[], private readonly now: () => number) {
    this.startedAt = now();
  }

  output(): string[] {
    const t = this.now() - this.startedAt;
    return this.steps.filter((s) => s.at <= t && s.write !== undefined).map((s) => s.write as string);
  }

  exitCode(): number | null {
    const t = this.now() - this.startedAt;
    const exit = this.steps.find((s) => s.exit !== undefined && s.at <= t);
    return exit ? (exit.exit as number) : null;
  }
}
import { ProcessHandle } from "../runtime/process";
import { Supervisor } from "../stream/supervisor";

export type ProcessFactory = (command: string) => ProcessHandle;

export class Launcher {
  private counter = 0;

  constructor(private readonly supervisor: Supervisor, private readonly spawn: ProcessFactory) {}

  launch(name: string, command: string): string {
    if (!name.trim()) throw new Error("job name is required");
    const id = `job-${String(++this.counter).padStart(4, "0")}`;
    this.supervisor.attach(id, name.trim(), this.spawn(command));
    return id;
  }
}
/**
 * In-process message bus shared with other services.
 *
 * Two lanes: "control" for small lifecycle messages and "data" for bulk payloads.
 * Each lane is FIFO. On drain, control messages are delivered before data so that
 * lifecycle changes are never stuck behind large payloads. No ordering is promised
 * between the two lanes.
 */
export type Lane = "control" | "data";

export type Subscriber<T> = (msg: T) => void;

export class EventBus<T> {
  private readonly queues: Record<Lane, T[]> = { control: [], data: [] };
  private readonly subscribers: Subscriber<T>[] = [];
  private delivered = 0;

  publish(lane: Lane, msg: T): void {
    this.queues[lane].push(msg);
  }

  subscribe(fn: Subscriber<T>): () => void {
    this.subscribers.push(fn);
    return () => {
      const i = this.subscribers.indexOf(fn);
      if (i >= 0) this.subscribers.splice(i, 1);
    };
  }

  /** Delivers everything queued so far. Messages published during delivery wait for the next drain. */
  drain(): number {
    const batch = [...this.queues.control, ...this.queues.data];
    this.queues.control = [];
    this.queues.data = [];
    for (const msg of batch) {
      for (const s of [...this.subscribers]) s(msg);
    }
    this.delivered += batch.length;
    return batch.length;
  }

  pending(): number {
    return this.queues.control.length + this.queues.data.length;
  }

  stats(): { delivered: number } {
    return { delivered: this.delivered };
  }
}
import { JobsHandler } from "./api/jobsHandler";
import { Router } from "./api/router";
import { ConsoleConfig, defaultConfig } from "./config";
import { JobEvent } from "./domain/events";
import { ProcessHandle } from "./runtime/process";
import { JobProjection } from "./projection/jobProjection";
import { Launcher, ProcessFactory } from "./service/launcher";
import { RetentionService } from "./service/retention";
import { JobViewStore } from "./store/jobViewStore";
import { Supervisor } from "./stream/supervisor";
import { EventBus } from "./transport/eventBus";
import { ManualClock } from "./util/clock";

export interface ConsoleApp {
  router: Router;
  clock: ManualClock;
  /** One host-loop iteration: advance time, poll jobs, deliver events. */
  tick(): void;
  /** Runs host-loop iterations for `ms` of simulated time. */
  runFor(ms: number): void;
  activeJobs(): string[];
}

export function createConsole(spawn: (command: string, now: () => number) => ProcessHandle, overrides: Partial<ConsoleConfig> = {}): ConsoleApp {
  const config: ConsoleConfig = { ...defaultConfig, ...overrides };
  const clock = new ManualClock();
  const bus = new EventBus<JobEvent>();
  const store = new JobViewStore();
  const projection = new JobProjection(store);
  bus.subscribe((e) => projection.apply(e));
  const supervisor = new Supervisor(bus, clock, config);
  const factory: ProcessFactory = (command) => spawn(command, () => clock.now());
  const launcher = new Launcher(supervisor, factory);
  const retention = new RetentionService(store, clock, config.retainFinishedMs);
  const router = new Router(new JobsHandler(store, launcher, projection, config));

  const tick = () => {
    clock.advance(config.tickMs);
    supervisor.tick();
    bus.drain();
    retention.sweep();
  };
  return {
    router,
    clock,
    tick,
    runFor(ms: number) {
      const end = clock.now() + ms;
      while (clock.now() < end) tick();
    },
    activeJobs: () => supervisor.activeJobs(),
  };
}

